<?php
namespace App\Filament\Widgets;
use App\Models\Registration; use App\Models\TireRequest; use Filament\Widgets\StatsOverviewWidget; use Filament\Widgets\StatsOverviewWidget\Stat;
class SpeedweekStatsOverview extends StatsOverviewWidget { protected function getStats(): array { $total=Registration::count(); $payment=Registration::selectRaw('payment_status, count(*) as aggregate')->groupBy('payment_status')->pluck('aggregate','payment_status')->map(fn($v)=>(int)$v)->all(); $transport=Registration::whereHas('package.features', fn($q)=>$q->where('key','motorcycle_transport_included')->where('included',true))->count(); $revenue=Registration::sum('total_amount_cents'); $depositDue=Registration::whereIn('payment_status',['unpaid','deposit_invoiced'])->sum('deposit_amount_cents'); $depositPaid=Registration::whereIn('payment_status',['deposit_paid','fully_paid'])->sum('deposit_amount_cents'); $finalDue=Registration::whereNotIn('payment_status',['fully_paid','refunded','credited'])->get()->sum(fn($r)=>max(0,$r->total_amount_cents-$r->deposit_amount_cents)); return [Stat::make('Total registrations',$total), Stat::make('Payment status', collect($payment)->map(fn($v,$k)=>$k.': '.$v)->join(' | ') ?: 'None'), Stat::make('Tire service requests', TireRequest::where('wants_tire_service',true)->count()), Stat::make('Motorcycle transport count',$transport), Stat::make('Revenue total','EUR '.number_format($revenue/100,2)), Stat::make('Deposit due / paid','EUR '.number_format($depositDue/100,2).' / EUR '.number_format($depositPaid/100,2)), Stat::make('Final due','EUR '.number_format($finalDue/100,2))]; } }
